#include "complete_maps_arithmetic.hpp"
#include <iomanip>
struct TRFiber {CFPoly u,v;G reduced;int saturated=0;};
P tr_embed(const CFPoly& p){std::vector<F> c;for(auto z:p.c)c.push_back(F(CFPoly{z}));return P(c);}
G tr_reduce(CFPoly u,CFPoly v,const CFPoly& h){require(u.degree()>=0,"transpose finite divisor support");u=u.monic();v=v%u;require(((v*v-h)%u).degree()<0,"transpose raw source incidence");while(u.degree()>3){auto q=(h-v*v).exact(u).monic();require(q.degree()<u.degree(),"transpose strict Cantor reduction");v=(-v)%q;u=q;}G r{tr_embed(u),tr_embed(v)};r.check();return r;}
TRFiber tr_fiber(const MMap& map,const Z& tx,const Z& ty){
    require(map.f.eval(tx,ty)==Z(0),"transpose target curve input");std::array<CFPoly,4> eq;for(int k=0;k<2;++k){Z power(1);for(auto& row:map.global.at(k?"V":"U").arr){auto c=pc_read_poly(row.at("c")),scale=map.den.exact(c);eq[size_t(2*k)]=eq[size_t(2*k)]+(pc_read_poly(row.at("a"))*scale).scale(power);eq[size_t(2*k+1)]=eq[size_t(2*k+1)]+(pc_read_poly(row.at("b"))*scale).scale(power);power=power*tx;}}eq[2]=eq[2]-map.den.scale(ty);
    TRFiber out;out.u=cf_gcd(cf_gcd(eq[0]*eq[3]-eq[2]*eq[1],eq[0]*eq[0]-eq[1]*eq[1]*map.h),eq[2]*eq[2]-eq[3]*eq[3]*map.h).monic();require(out.u.degree()>=0,"nonzero transpose elimination support");for(;;){auto g=cf_gcd(out.u,map.den);if(g.degree()==0)break;out.u=out.u.exact(g).monic();++out.saturated;}
    require(out.u.degree()>0&&out.u.degree()<=9,"transpose affine degree at most9");auto[g,s,t]=xgcd(eq[1]%out.u,eq[3]%out.u);auto[gg,ss,tt]=xgcd(g,out.u);require(gg.degree()==0,"transpose source y separation");out.v=(-(s*eq[0]+t*eq[2])*ss)%out.u;require(((out.v*out.v-map.h)%out.u).degree()<0,"transpose recovered source equation");require(((eq[0]+eq[1]*out.v)%out.u).degree()<0&&((eq[2]+eq[3]*out.v)%out.u).degree()<0,"transpose both graph equations");out.reduced=tr_reduce(out.u,out.v,map.h);return out;
}
void tr_emit_g(const G& p){std::cout<<"{\"U\":";cf_emit_poly(rational(p.u));std::cout<<",\"V\":";cf_emit_poly(rational(p.v));std::cout<<'}';}
int main(int argc,char** argv){try{
    require(argc==5,"usage: transpose_maps study global.json bridge.json formal.json");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;auto global=read_json(argv[2]),bridge=read_json(argv[3]),formal=read_json(argv[4]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),points=read_json(root+"/evidence/destination-relations-v2/result.json");EBPoly f;for(auto& row:model.at("terms").arr){auto e=row.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(row.at("coefficient").scalar)));}MMap map(global,f);std::vector<int> ids{0,1,2,3,223,224,225};int final=points.at("split_fibers").arr[0].at("point_indices").arr[0].integer();if(std::find(ids.begin(),ids.end(),final)==ids.end())ids.push_back(final);std::vector<TRFiber> fibers(ids.size());std::vector<std::string> errors(ids.size());std::vector<GBImage> images(ids.size());std::vector<G> source_classes(ids.size());
    for(size_t k=0;k<ids.size();++k){try{auto& p=points.at("points").arr.at(size_t(ids[k]));fibers[k]=tr_fiber(map,Z(mpz_class(p.at("x").scalar)),Z(mpz_class(p.at("y").scalar)));std::cerr<<"transpose point "<<ids[k]<<" finite degree="<<fibers[k].u.degree()<<" saturation="<<fibers[k].saturated<<'\n';}catch(const std::exception& e){errors[k]=e.what();std::cerr<<"transpose point "<<ids[k]<<" rejected: "<<e.what()<<'\n';}}
    std::vector<GBImage> nonzero;std::vector<int> positions(ids.size(),-1);if(errors[0].empty())for(size_t k=1;k<ids.size();++k)if(errors[k].empty()){try{source_classes[k]=fibers[k].reduced.add(fibers[0].reduced.neg());if(source_classes[k]==G{})continue;images[k]=gb_image(source_classes[k],global,f);positions[k]=int(nonzero.size());nonzero.push_back(images[k]);}catch(const std::exception& e){errors[k]=e.what();}}
    QuarticKM km(model,points);GBAdapter adapter(km,formal,nonzero);auto negative=km.negate(adapter.baseline());auto qref=km.point_class(ids[0]);auto negref=km.negate(qref);std::vector<bool> compositions(ids.size(),false);int passes=0;for(size_t k=1;k<ids.size();++k)if(errors[0].empty()&&errors[k].empty()){try{Class mapped=positions[k]<0?km.identity:km.add(adapter.encode(images[k]),negative);auto qdiff=km.add(km.point_class(ids[k]),negref);auto expected=pc_times(km,qdiff,3);require(km.equal(mapped,expected),"transpose phi psi composition3");compositions[k]=true;++passes;require(!km.equal(mapped,km.add(expected,km.point_class(km.fibers[1].support[0]))),"altered target composition rejects");std::cerr<<"composition3 point "<<ids[k]<<" passed\n";}catch(const std::exception& e){errors[k]=e.what();}}
    if(fibers[0].u.degree()>0)rejects([&]{auto v=fibers[0].v+CFPoly{Z(1)};require(((v*v-map.h)%fibers[0].u).degree()<0,"changed transpose y");},"changed transpose y");
    std::cout<<"{\"scope\":\"P192-kernel3-rational-transpose-correspondence\",\"standing\":\"producer-unverified\",\"composition3_passes\":"<<passes<<",\"target_addflips\":"<<km.flips<<",\"all_reverse_interfaces_complete\":false,\"fixtures\":[";for(size_t k=0;k<ids.size();++k){if(k)std::cout<<',';std::cout<<"{\"index\":"<<ids[k]<<",\"source_degree\":"<<fibers[k].u.degree()<<",\"saturation_steps\":"<<fibers[k].saturated<<",\"source_U\":";cf_emit_poly(fibers[k].u);std::cout<<",\"source_V\":";cf_emit_poly(fibers[k].v);std::cout<<",\"reduced\":";tr_emit_g(fibers[k].reduced);std::cout<<",\"difference\":";tr_emit_g(source_classes[k]);std::cout<<",\"composition3\":"<<(compositions[k]?"true":"false")<<",\"error\":"<<std::quoted(errors[k])<<'}';}std::cout<<"]}\n";bool failed=!errors[0].empty();for(size_t k=1;k<errors.size();++k)failed|=!errors[k].empty();return failed?2:0;
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
